  "heroglyph.flow.dogCharacter.slide.guardian.desc": "يحرس الباب كأنه بوابة العالم الآخر. ينبح أولًا، ولا يسأل أبدًا.",
  "heroglyph.flow.dogCharacter.slide.player.desc": "يبيع روحه مقابل رمية كرة أخرى. أعظم فرحه: لعبته المفضّلة.",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "لا زر إيقاف. لا حاجة إلى بطاريات. السؤال الأكثر شيوعًا: ماذا يتعاطى هذا الكلب؟",
  "heroglyph.flow.dogCharacter.slide.maverick.desc": "قرصان عصري له عالمه وقوانينه. السمع الانتقائي قانونه الأول.",
  "heroglyph.flow.dogCharacter.slide.waterlover.desc": "هناك نوعان من الكلاب — وأحدهما قد يُحسب سمكة. فراء مبلول: سعادة بنسبة 100%.",
  "heroglyph.flow.dogCharacter.slide.gourmet.desc": "الطعام مهمّته. التزام تام، صفر تردّد — وسيأكل أيضًا ما لم تأكله أنت.",
  "heroglyph.flow.dogCharacter.slide.lover.desc": "لا يعرف شيئًا اسمه غريب. يستقبل ساعي البريد كتوأم روح افتقده طويلًا. في كل مرة.",
  "heroglyph.flow.dogCharacter.slide.chiller.desc": "أتقن الفن العريق في ألّا يفعل شيئًا على الإطلاق — وبكل أناقة.",
