  "notFound.code": "404",
  "notFound.message": "عذراً! الصفحة غير موجودة",
  "notFound.returnHome": "العودة للرئيسية",
  "about.origin.title": "الـ<br />أصل",
  "about.origin.sub": "مرّر واقرأ",
  "about.origin.skip": "أو تخطَّ",
  "about.crawl.intro": "منذ عشر سنوات، في ملجأ في قلب أوروبا….",
  "about.crawl.episode": "الحلقة الأولى",
  "about.crawl.faith": "إيمان جديد",
  "about.crawl.p1": "في عام 2016، وصل ثمانية جراء سوداء إلى الملجأ، مرميّة في صندوق واحد. وجد سبعة منها بيتاً. أكبرها لم يُرِدْه أحد — انتظر سنة كاملة. كان اسمه Hekthor.",
  "about.crawl.p2": "ذات يوم جاء زوجان إلى الملجأ لرؤية Sindy، أنثى بيضاء صغيرة أرادا تبنّيها. بمحض الصدفة، كان Hekthor في قفصها في ذلك الوقت — كان قفصه يُنظَّف للتو. الرجل الذي جاء للمرافقة فقط ولم يكن يريد كلباً أبداً، وقع في حب الكلب الأسود الذي كان يراه لأول مرة.",
  "about.crawl.p3": "بعد أسبوع كانا معاً، وبدأت قصة جميلة. تغيّرت حياة الرجل كلياً، وفهم مع الوقت شيئاً واحداً: فقط من يمتلك كلباً ويعرف كيف يبدو حبّ الكلب، يستطيع حقاً مساعدة الكلاب المحتاجة.",
  "about.crawl.p4": "وهكذا وُلد الـ Heroglyph — رمز يهدف إلى توحيد محبّي الكلاب في كل مكان في أكبر مجتمع عرفه العالم. مجتمع سيقف معنا ومع كلابنا ومع الأجيال القادمة — لأناس لا يخافون الاعتراف بأن الكلب ليس مجرد حيوان، بل كائن يجعلنا بشراً أفضل.",
  "about.crawl.p5": "الآن تبدأ الرحلة نحو أول هدف — إنشاء 1,000,000 Heroglyph. ويمكنك أن تكون جزءاً منه. لأن الوحيدين المجانين بما يكفي للاعتقاد بأنهم يمكنهم تغيير العالم هم من يفعلون ذلك فعلاً.",
  "about.crawl.p6": "نؤمن بالكلب.",
  "about.timeline.heading": "قصة Dogypt",
  "about.milestone.1.year": "2017",
  "about.milestone.1.tag": "الملجأ",
  "about.milestone.1.title": "كنز في الملجأ",
  "about.milestone.1.body": "كلب أسود لم يُرِدْه أحد كان ينتظر خلف سياج الملجأ. أصبح اسمه Hekthor. تبنّيه لم يكن إنقاذاً — بل كان بداية كل شيء.",
  "about.milestone.2.year": "2018",
  "about.milestone.2.tag": "الرابطة",
  "about.milestone.2.title": "رابطة إلى الأبد",
  "about.milestone.2.body": "جرّني عبر أصعب مرحلة في حياتي دون أن ينبس بكلمة. كل محبّ للكلاب يعرف هذا — إنهم يحملونك بالضبط عندما تسقط.",
  "about.milestone.3.year": "2019",
  "about.milestone.3.tag": "الرحلة",
  "about.milestone.3.title": "المشوار الذي صار كتاباً",
  "about.milestone.3.body": "معاً مشينا عبر سلوفاكيا — 42 يوماً، 800 كيلومتر، ووعد صامت واحد. صار ذلك الطريق كتاباً: «Cesta s Hrdinom» — الطريق مع بطل.",
  "about.milestone.4.year": "2022",
  "about.milestone.4.tag": "الاسم",
  "about.milestone.4.title": "أمة محبّي الكلاب",
  "about.milestone.4.body": "الأهرامات، الغموض، مجد مصر الأبدي — سحر البشرية منذ آلاف السنين. اربط ذلك بالحب اللانهائي للكلب وستحصل على DOGYPT. ختمت الفكرة في إكسبو دبي 2022، متنكراً في زي فرعون.",
  "about.milestone.5.year": "الآن",
  "about.milestone.5.tag": "Dogypt",
  "about.milestone.5.title": "الرحلة تبدأ بك",
  "about.milestone.5.body": "DOGYPT حركة لكل من غيّر كلبٌ حياتَه. مبنية على أقدم وأصدق رابطة على الأرض. Hekthor هو المؤسس رقم 1. أنت التالي.",
  "about.outro.quoteLead": "لم يكن",
  "about.outro.quoteTail": "\"مجرد كلب.\"",
  "about.outro.body": "أنت تعرف الشعور بالفعل — أن الكلب ليس شيئاً تمتلكه، بل <strong>شخص تحبه</strong>. الآن تخيّل ذلك الحب منظّماً ومتصلاً، <strong>قوياً بما يكفي لتغيير الأمور.</strong> وهذا هو سبب وجود <strong>DOGYPT</strong>.",
  "about.outro.name1": "Matej",
  "about.outro.and": "و",
  "about.outro.name2": "Hekthor",
  "about.outro.cta": "كن دوغبتيًا",
