  "wall.hero.total": "1,000,000",
  "wall.hero.dogs": "كلب",
  "wall.hektor.msg": "Hekthor، أنت بطلي الأعظم، وأعزّ أصدقائي، ورفيقي الوفيّ، ومُعلّمي الذي لا يرحم — أنت أجمل قصة في حياتي. بسببك أسّستُ ديناً للكلاب، وأدركتُ أن حبّي ليس استثنائياً في شيء — فكل من أحبّ كلباً يوماً يشعر في قلبه بالشيء نفسه تماماً. شكراً لك على أفضل حياة عشناها معاً. أحبّك.",
  "wall.info.title": "1,000,000 كلب.<br/>هل سننجح؟",
  "wall.info.body": "DOGYPT حركة لمحبّي الكلاب. كل كلب يحصل على Heroglyph فريد — مكانه الدائم في القطيع العالمي. نجمع مليون بطل. كن من الأوائل.",
