  "whatNext.s1.title": "الخطوة الأولى",
  "whatNext.s1.hook": "خطوة صغيرة للإنسان — قفزة عملاقة لعالم الكلاب.",
  "whatNext.s1.body": "Heroglyph الخاص بك أعلن للتو أنك جزء من حركة تكرّم الكلاب في أرجاء العالم. <b>الخطوة الأولى تمّت.</b>",
  "whatNext.s2.title": "أنت الآن دوغبتي",
  "whatNext.s2.hook": "أنت لستَ مجرد محبّ للكلاب — أنت مؤمن بمقود.",
  "whatNext.s2.body": "مسجَّل في WALL إلى الأبد. كل واحد منا يعطي قليلاً — و<b>معاً، نعطي الكلاب ما يكفي.</b>",
  "whatNext.s3.title": "كن جزءاً من التغيير",
  "whatNext.s3.hook": "كفّ واحدة تترك أثراً. مليون كفّ تصنع طريقاً.",
  "whatNext.s3.body": "ساعدنا للوصول إلى مليون Heroglyph — ادعُ أصدقاءك للانضمام. <b>المزيد من heroglyphs = المزيد من الخير لكل كلب.</b>",
  "whatNext.s4.title": "ابقَ على تواصل",
  "whatNext.s4.hook": "الباب مفتوح. Pack في الانتظار.",
  "whatNext.s4.body": "تحقق من بريدك الإلكتروني وسجّل الدخول إلى ملفك الشخصي — هناك سنبقى على تواصل. <b>تطبيق مدى الحياة لكلابنا في الطريق.</b>",
