  "entry.subtitle": "هذه ليست مزحة. كل دينٍ جادّ عليه أن يُعلن هذه الأمور.",
  "entry.criteria.theology.title": "اللاهوت",
  "entry.criteria.theology.body": "أعزّ صديق، وحارس، ومعلّم، ورفيق في كل مغامرة. الكلب يمنح الحب بلا شروط — والسير بجانبه يجعلنا أكثر إنسانية.",
  "entry.criteria.canon.title": "النصّ المقدّس",
  "entry.criteria.canon.body": "لكل دين نصّه المقدّس. نصّنا هو DOGMA: رابطتنا مع الكلب مكتوبةً عبر اثني عشر فصلاً، متاحةً للقراءة مجاناً على dogma.dogypt.com.",
  "entry.criteria.community.title": "المجتمع",
  "entry.criteria.community.body": "نحن محبّو الكلاب أصحاب هدف. وحدنا، لا يستطيع كلٌّ منّا تغيير شيء يُذكر — ومعاً، لا حدّ لقوّتنا.",
  "entry.criteria.symbol.title": "الرمز",
  "entry.criteria.symbol.body": "لكل دين علامته. علامتنا هي Heroglyph: رمز مقدّس فريد لكل كلب، مفهوم بأي لغة وفي أي مكان.",
  "entry.criteria.ritual.title": "الطقس",
  "entry.criteria.ritual.body": "المشي. علاج يومي يُبقي الجسد والعقل في حال جيدة — والروح أيضاً. أقدم طقس نمارسه فعلاً دون أن يُطلب منّا.",
  "entry.criteria.vision.title": "الرؤية",
  "entry.criteria.vision.body": "أن نرفع الرابطة بين الإنسان والكلب — وأن نناضل من أجل الاحترام والحياة الأفضل التي يستحقّها كل كلب.",
