  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. داخل القطيع: ما يراه الأعضاء الآخرون",
  "privacy.s12.body": "يصف الفصل 3 شبكة GodsGrid العامة. داخل القطيع — في المنطقة المخصّصة للأعضاء فقط — يرى الأعضاء المسجَّلون الآخرون أكثر من ذلك: اسمك الأول، رقمك الدوغبتي، اسم كلبك وصورته، الصفات التي أدخلتها عن كلبك، الرحلات التي سجّلتها أو أعلنت عنها، تقييماتك وتعليقاتك، وكل ما كتبته على ملفك الشخصي. لا يرون عنوان بريدك الإلكتروني، ولا عنوانك البريدي، ولا بيانات الدفع، ولا رسائلك مع أي شخص آخر. حين تُعلن عن رحلة كمفتوحة، يصبح المسار والتاريخ وكلبك مرئيين لكل عضو بحيث يمكنه طلب الانضمام — هذا ما يعنيه الإعلان عنها. الرحلة التي تبقيها خاصة يراها فقط أنت والأشخاص الذاهبون فعلًا. أنت من يختار أيّ الحالتين تريد، ويمكنك تغيير ذلك في أي وقت.",
  "privacy.s13.title": "13. الرسائل والبلاغات",
  "privacy.s13.body": "تُخزَّن الرسائل الخاصة بين الأعضاء في قاعدة بياناتنا (Supabase) حتى تبقى المحادثات بين الجلسات. الأساس القانوني: المادة 6(1)(ب) من GDPR — فهي جزء من العضوية التي دفعت ثمنها. لا نقرؤها بشكل روتيني ولا نستخدمها مطلقًا للإعلان أو التوصيف. نفتح المحادثة فقط عند الإبلاغ عنها، أو عند التحقيق في إساءة أو حادثة أمنية محدّدة، أو حين يتطلّب القانون ذلك. يُخزِّن البلاغ السبب الذي اخترته، وملاحظتك الاختيارية، وإشارة إلى ما بلّغت عنه — لا نسخة منفصلة منه. يُخزَّن الحظر كزوج من معرّفات الأعضاء. إذا حذفت حسابك تُحذف رسائلك معه؛ أما النسخة في محادثة الطرف الآخر فتبقى، وتظهر كأنها من عضو محذوف، لأن تلك المحادثة تخصّه أيضًا.",
  "terms.s12.title": "12. المحتوى الذي تنشره",
  "terms.s12.body": "بالإضافة إلى HEROGLYPH الخاص بك، يمكنك نشر محتوى داخل القطيع: صور الرحلات، المسارات والمواقع، أوصاف الرحلات، التقييمات، التعليقات والأسئلة، وكل ما تكتبه على ملفك الشخصي. حين تُعلّم رحلة بأنها مقطوعة، يرى الأعضاء الآخرون اسمك الأول والكلاب التي قطعتها معك. تحتفظ بملكية كل ما تنشره. بنشرك له، تمنح شركة DOGYPT s.r.o. ترخيصًا عالميًا غير حصري وبلا مقابل لتخزين هذا المحتوى وعرضه وتكييفه بغرض تشغيل الخدمة والترويج لها — مثل إظهار صورة رحلتك على الخريطة، أو في قائمة الرحلات، أو على بطاقة مشاركة. يستمر الترخيص طالما المحتوى موجود في الخدمة؛ وينتهي بإزالة المحتوى أو حسابك، باستثناء النسخ الاحتياطية التي تنتهي في دورتها العادية. لا نبيع محتواك ولا نرخّصه لأي طرف آخر لاستخدامه الخاص. لا تنشر إلا ما لديك الحق في نشره — ويشمل ذلك الصور التي التقطها شخص آخر والأشخاص الذين يمكن التعرّف عليهم فيها.",
  "terms.s13.title": "13. الرسائل بين الأعضاء",
  "terms.s13.body": "يمكن للأعضاء التراسل مباشرة. الرسائل خاصة بين المشاركين — لا نقرؤها بشكل روتيني ولا نستخدمها أبدًا للإعلان. تُخزَّن على خوادمنا حتى تبقى المحادثة موجودة عند عودتك، ويمكننا قراءة محادثة في ثلاث حالات: حين يبلّغ عنها أحد، أو حين نحقّق في إساءة أو حادثة أمنية محدّدة، أو حين يتطلّب القانون ذلك. يمكنك حظر عضو آخر في أي وقت؛ الحظر فوري ويعمل في الاتجاهين. تعامل مع الرسائل كما تتعامل مع أي محادثة عبر الإنترنت — لا ترسل تفاصيل الدفع أو كلمات المرور أو مستندات لا تريد أن تُخزَّن.",
  "terms.s14.title": "14. البلاغات والإشراف",
  "terms.s14.body": "يمكن الإبلاغ عن الملفات الشخصية والرحلات والمحادثات. يصل البلاغ إلينا ويقرؤه إنسان — اليوم هو المؤسّس Matej Stacho. نهدف إلى مراجعة كل بلاغ في غضون 7 أيام. وتبعًا لما نجده، قد لا نفعل شيئًا، أو نحذف المحتوى، أو نحذّر العضو، أو نحدّ مما يمكنه نشره، أو نغلق حسابه. إذا تصرّفنا حيال محتواك سنوضح لك السبب عبر البريد الإلكتروني، ويمكنك الرد والاعتراض عليه. قد نزيل المحتوى أيضًا من تلقاء أنفسنا إذا خالف المادة 7. الإساءة المتعمّدة أو المتكرّرة — كالتحرّش أو البريد العشوائي أو الرحلات المزيّفة أو المحتوى المتعلق بالقُصَّر — تنهي الحساب دون تحذير إضافي.",
  "dogPage.bonesForDog": "انضمّ عبر هذه الصفحة وسيحصل {dog} على 20 BONES.",
  "dogPage.bonesNote": "BONES هي عملة DOGYPT — تُضاف إلى حساب المالك.",
