  "pack.cal.life.rec.pebbles.exact": "22 سنة و189 يومًا",
  "pack.cal.life.recSince": "منذ {year}",
  "pack.cal.life.tip.weight.title": "الحفاظ على الرشاقة هو الشيء الوحيد المُثبت",
  "pack.cal.life.tip.weight.body": "من كل ما يمكنك فعله لكلبك، هناك شيء واحد له أقوى دليل على طول العمر: ألا تتركه يزيد وزنه. الفرق بين كلب رشيق وكلب يعاني من زيادة طفيفة في الوزن يُقاس بالسنوات لا بالشهور. يجب أن تستطيع تحسّس أضلاعه دون الضغط.",
  "pack.cal.life.tip.move.title": "الحركة على تضاريس حقيقية، لا دورة حول المبنى",
  "pack.cal.life.tip.move.body": "الأرض غير المستوية تُحافظ على نشاط المفاصل والعضلات والعقل. كل رحلة تسجّلها تتحوّل إلى أسبوع غامق على هذه الشبكة — والأسابيع الغامقة هي الشيء الوحيد الذي تستطيع التأثير فيه فعلًا.",
  "pack.cal.life.tip.food.title": "طعام يتعرّف الكلب عليه كطعام",
  "pack.cal.life.tip.food.body": "كلما قلّت الخطوات بين المكوّن الخام والوعاء، قلّت الأمور التي قد تسوء في الطريق. الحبيبات الجافة ليست خطيئة، لكنها ليست نظامًا غذائيًا أيضًا — إنها اختصار.",
  "pack.cal.life.tip.chem.title": "الكيمياء فقط عند الحاجة الفعلية",
  "pack.cal.life.tip.chem.body": "علاجات الطفيليات على مدار العام، والتخدير من أجل الراحة، والمضادات الحيوية «للاحتياط» هي قرارات لا عادات. اسأل عن كل واحدة منها: ماذا يحدث لو تجاوزتها؟ وحيثما كانت الإجابة «لا شيء»، تجاوزها.",
  "pack.cal.life.tip.stress.title": "الراحة تُحسب بقدر الحركة",
  "pack.cal.life.tip.stress.body": "الكلب الذي يظل في حالة تأهّب دائم يستهلك جسده من الداخل. النوم دون إزعاج، واليوم المنتظم، والهدوء بعد الجهد ليست كسلًا — بل الساعات التي يُصلح فيها الجسد نفسه.",
  "pack.cal.life.tip.protocol.title": "بروتوكول بدل الركض المذعور إلى الطبيب البيطري",
  "pack.cal.life.tip.protocol.body": "إزالة الديدان وفحص البراز وفحص الدم لها نوافذها الخاصة في التقويم. الكلب الذي تفحص دمه مرتين في السنة لا يُعالَج — بل يُستبَق المرض لديه.",
  "pack.cal.life.tip.joints.title": "تُعالَج المفاصل قبل أن تبدأ بالألم",
  "pack.cal.life.tip.joints.body": "كلبك الآن في فئة كبار السن. كورس المفاصل له نافذته في التقويم من نوفمبر — ليس لأنه يَعرج، بل حتى لا يضطر إلى ذلك أبدًا.",
