  "pack.hero.popStatusEyebrow": "الحالة",
  "pack.hero.popPawtner1": "Pawtner هو مكانتك في القطيع — أنت رفيق كلب أنشأت له HEROGLYPH. بلا heroglyph، لا تكون دوغبتيًا.",
