  "pack.network.ads.body": "الإعلانات المدفوعة طريقة غير فعّالة جدًا لإيجاد عشّاق كلاب جدد — وطريقة لرمي أموالنا على الشركات الكبرى. الأفعل بكثير هو مكافأة أعضاء الحركة مباشرة على نشاطهم. يوجد شرط واحد: <strong style=\"font-weight:600\">لن ينجح الأمر فعليًا إلا إذا خرجت وأخبرت من حولك عنّا</strong> :)",
