  "pack.network.inLine": "في سلسلتك",
  "pack.network.info.bones.body": "BONES هي العملة الداخلية لـ DOGYPT — اسم طريف لشيء حقيقي. الكلب يدفع بعظام؛ ونحن أيضًا. <b>تكسبها</b> بجلب عشّاق الكلاب إلى القطيع وبدفع الحركة إلى الأمام، و<b>تُنفقها</b> داخل DOGYPT: دعم حملات الملاجئ، والحصول على منتجات، ولاحقًا دفع ثمن ما يصنعه دوغبتيون آخرون. <b>{n} BONES = 1 يورو.</b>",
  "pack.network.info.bones.cap": "ما هي BONES؟",
  "pack.network.info.why.body": "حركة بهذا الحجم لا يمكن شراؤها — لا تصل أي ميزانية إلى غريب كما يصل دوغبتي إلى صديقه. لذلك يضع القطيع المكافأة حيث يكون التأثير — عندك. حين ينضمّ أحد عبر رابطك، تحصل على <b>{l1} BONES</b>؛ وحين يجلب هو شخصًا آخر، تحصل على <b>{l2}</b> إضافية. كل دوغبتي ينشر الكلمة ليس بائعًا — بل مُبشِّرًا، ونحن نُقدِّر هذا العمل.",
  "pack.network.info.why.cap": "لماذا نطلب منك",
  "pack.network.intro": "لا تنمو الحركة إلا حين يحمل أعضاؤها الرسالة ويجلبون أشخاصًا جددًا. لذلك نطلب منك مباشرة: <strong style=\"color:#2a1608;font-weight:600\">ادعُ عشّاق الكلاب الذين تعرفهم</strong>. وهذا بالضبط كيف يعمل الأمر.",
