  "onepage.fin.p1": "مرحباً، أنا Matthew. قبل تسع سنوات تغيّرت حياتي — بسبب كلب من ملجأ. بعدما شعرت بقوة حبّ الكلب، راودتني رؤية لكيفية ردّ الجميل للكلاب — ليس لكلبي وحده، بل لكل كلب في العالم.",
  "onepage.fin.p2": "في ذلك الوقت كانت مجرد فكرة — وبفضل الذكاء الاصطناعي أستطيع أخيراً أن أبنيها. كلما كان الطقس جميلاً أكون في رحلات مع Hekthor، وبينما يرتاح هو أعمل بجدّ على DOGYPT. أنا مهووس بهذه المهمة — أضحّي بكل شيء من أجلها وأضع فيها كل يورو أملكه. يقول المقرّبون مني إنني حالم أخاطر كثيراً — لكنني مقتنع بأن هذه الفكرة تستحق القتال من أجلها، وأن الأمر مسألة وقت فقط.",
  "onepage.fin.p3": "رجاءً لا تتركنا ننتظر — انضم إلينا اليوم، حتى لا أضطر إلى الانتقال إلى الخطة ب (OnlyFans).",
  "onepage.fin.aboutMore": "المزيد عني",
  "onepage.fin.liveHead": "الحالة المباشرة",
  "onepage.fin.aiLine": "يُبنى هذا المشروع بحبّ <b>الكلاب</b> — و<b>الذكاء الاصطناعي</b>.",
