  "onepage.hbook.0.title": "كان يا ما كان…",
  "onepage.hbook.0.glyph": "heroglyph الخاص بـ Hekthor",
  "onepage.hbook.0.sub": "Hekthor · الكلب رقم 1",
  "onepage.hbook.0.cap": "المرآة",
  "onepage.hbook.1.ini": "و",
  "onepage.hbook.1.lead": "لد غير مرغوب فيه. رُمي في صندوق، حيث انتظر مع إخوته الموت.",
  "onepage.hbook.1.txt": "انتهت ثمانية أرواح صغيرة في ملجأ. سبعة منها وجدت بيتاً. وبقي واحد فقط — الأكبر، صاحب أكبر طباع. وبعد عام، بمحض الصدفة، التقى بـ Matej الذي لم يكن يخطط يوماً لاقتناء كلب. اشتعلت شرارة، ومنذ يونيو 2017 يمشيان معاً في الحياة.",
  "onepage.hbook.1.cap": "ثمانية في صندوق",
  "onepage.hbook.2.ini": "أ",
  "onepage.hbook.2.lead": "نقذ حياة إنسان. جاء في أقسى مواسمها.",
  "onepage.hbook.2.txt": "في أحلك الأوقات كان مرساة Matej — انتشله من الأفكار المظلمة، ومن الشقة إلى الطبيعة. أولاً الشوارع القريبة، ثم الغابات والجبال. عبرا سلوفاكيا كلها (820 كم) وقاما برحلات برية عبر أوروبا. ربطتهما المغامرة والحياة الحرة على الطريق.",
  "onepage.hbook.2.cap": "من المكتب إلى العالم",
  "onepage.hbook.3.ini": "ر",
  "onepage.hbook.3.lead": "وحه النقية حملت رؤية حركة عالمية لمحبّي الكلاب.",
  "onepage.hbook.3.txt": "الحياة مع كلب هي أجمل فصل في حياة أي إنسان. أصحاب الكلاب نوع آخر من الناس — يواجهون المشكلات المحددة نفسها مراراً وتكراراً، ويربطهم حبّهم للكلاب. فماذا لو تحوّلت هذه القصة إلى شيء مفيد؟",
  "onepage.hbook.3.cap": "ولادة رؤية",
  "onepage.hbook.4.ini": "ع",
  "onepage.hbook.4.lead": "شر سنوات جميلة خلفه، وعشر أخرى على الأقل أمامه!",
  "onepage.hbook.4.txt": "ألهم Hekthor صاحبه Matej ليتعلم كل شيء عن الكلاب — علم النفس والتدريب والرياضة، وقبل كل شيء طول العمر. كل هذه المعرفة ستخدم الجميع في DOGYPT: ليست شبكة اجتماعية فاخرة أخرى، بل شبكة بمحتوى ذي معنى. وكل ذلك بفضل كلب ملجأ «عادي».",
  "onepage.hbook.4.cap": "المؤسس رقم 1",
  "onepage.hbook.5.ini": "ي",
  "onepage.hbook.5.lead": "عيش اليوم في سلوفاكيا — في الغابات والجبال وعلى ضفاف البحيرات.",
  "onepage.hbook.5.txt": "جلب الأشياء من الماء هو حبّه الأكبر. هو في قمة لياقته، حكيم ومتواضع وأفضل رفيق يمكن أن يتمناه أي إنسان. وحين لا نكون في الخارج، يحرس البيت من قطّين هما Gary وYby، أنقذهما من الشارع.",
  "onepage.hbook.5.cap": "حارس البيت",
